class DebateCreate(BaseModel):
    topic: str
    description: str


class Debate(BaseModel):
    id: str
    topic: str
    description: str
    created_at: str


class ArgumentCreate(BaseModel):
    side: Literal["for", "against"]
    content: str


class Argument(BaseModel):
    id: str
    debate_id: str
    side: Literal["for", "against"]
    content: str
    created_at: str


# --- Endpoints ---

@app.post("/debates", response_model=Debate, status_code=201)
def create_debate(body: DebateCreate) -> Debate:
    debate_id = str(uuid4())
    debate = {
        "id": debate_id,
        "topic": body.topic,
        "description": body.description,
        "created_at": datetime.now(timezone.utc).isoformat(),
    }
    debates[debate_id] = debate
    arguments[debate_id] = []
    return Debate(**debate)


@app.get("/debates", response_model=list[Debate], status_code=200)
